import 'dart:async';import 'dart:math';import 'dart:typed_data';import 'package:flutter/foundation.dart';enum PaddingScheme { constantTime, randomNoise, packetMorphing }class TrafficPattern {  final String nodeId;  final List<int> packetSizes;  final List<int> interArrivalTimes;  final DateTime startTime;  final DateTime endTime;  final int totalPackets;  TrafficPattern({    required this.nodeId,    required this.packetSizes,    required this.interArrivalTimes,    required this.startTime,    required this.endTime,    required this.totalPackets,  });  double get averagePacketSize {    if (packetSizes.isEmpty) return 0;    return packetSizes.reduce((a, b) => a + b) / packetSizes.length;  }  double get averageInterArrivalTime {    if (interArrivalTimes.isEmpty) return 0;    return interArrivalTimes.reduce((a, b) => a + b) / interArrivalTimes.length;  }  Duration get duration => endTime.difference(startTime);  double get packetsPerSecond {    final seconds = duration.inSeconds;    if (seconds == 0) return 0;    return totalPackets / seconds;  }}class TrafficPadder {  final Random _random = Random.secure();  final PaddingScheme _scheme;  int _targetPacketSize;  final int _minPadding;  final int _maxPadding;  static const int _defaultTargetPacketSize = 512;  static const int _defaultMinPadding = 16;  static const int _defaultMaxPadding = 256;  final List<TrafficPattern> _observedPatterns = [];  static const int _maxPatternHistory = 100;  final _paddedPacketController = StreamController<Uint8List>.broadcast();  Stream<Uint8List> get paddedPackets => _paddedPacketController.stream;  int _totalPacketsPadded = 0;  int _totalBytesPadded = 0;  TrafficPadder({    PaddingScheme scheme = PaddingScheme.constantTime,    int targetPacketSize = _defaultTargetPacketSize,    int minPadding = _defaultMinPadding,    int maxPadding = _defaultMaxPadding,  })  : _scheme = scheme,        _targetPacketSize = targetPacketSize,        _minPadding = minPadding,        _maxPadding = maxPadding;  Uint8List padPacket(Uint8List original) {    final currentSize = original.length;    final paddingNeeded = _calculatePadding(currentSize);    if (paddingNeeded <= 0) {      _paddedPacketController.add(original);      return original;    }    final padded = _applyPadding(original, paddingNeeded);    _totalPacketsPadded++;    _totalBytesPadded += paddingNeeded;    _paddedPacketController.add(padded);    return padded;  }  int _calculatePadding(int currentSize) {    if (currentSize >= _targetPacketSize) {      return 0;    }    switch (_scheme) {      case PaddingScheme.constantTime:        final remainder = currentSize % _minPadding;        return remainder == 0 ? _minPadding : _minPadding - remainder;      case PaddingScheme.randomNoise:        return _minPadding + _random.nextInt(_maxPadding - _minPadding);      case PaddingScheme.packetMorphing:        return _targetPacketSize - currentSize;    }  }  Uint8List _applyPadding(Uint8List original, int paddingSize) {    final paddedData = Uint8List(original.length + paddingSize);    paddedData.setAll(0, original);    switch (_scheme) {      case PaddingScheme.constantTime:        for (int i = 0; i < paddingSize; i++) {          paddedData[original.length + i] = 0x00;        }        break;      case PaddingScheme.randomNoise:        for (int i = 0; i < paddingSize; i++) {          paddedData[original.length + i] = _random.nextInt(256);        }        break;      case PaddingScheme.packetMorphing:        for (int i = 0; i < paddingSize; i++) {          paddedData[original.length + i] = _random.nextInt(256);        }        break;    }    return paddedData;  }  Uint8List generateDummyTraffic(int size) {    final dummy = Uint8List(size);    for (int i = 0; i < size; i++) {      dummy[i] = _random.nextInt(256);    }    return dummy;  }  Uint8List generateConstantPadding(int size) {    final padded = Uint8List(size);    for (int i = 0; i < size; i++) {      padded[i] = _random.nextInt(2);    }    return padded;  }  Uint8List morphPacket(Uint8List packet) {    if (packet.length < 64) return padPacket(packet);    final morphSize = _targetPacketSize + _random.nextInt(_maxPadding);    final morphed = Uint8List(morphSize);    morphed.setAll(0, packet);    for (int i = packet.length; i < morphSize; i++) {      morphed[i] = _random.nextInt(256);    }    _totalPacketsPadded++;    _totalBytesPadded += (morphSize - packet.length);    _paddedPacketController.add(morphed);    return morphed;  }  Uint8List stripPadding(Uint8List paddedPacket) {    if (paddedPacket.length <= _targetPacketSize) {      return paddedPacket;    }    int actualEnd = paddedPacket.length;    if (_scheme == PaddingScheme.constantTime) {      for (int i = paddedPacket.length - 1;          i >= 0 && i >= paddedPacket.length - _maxPadding;          i--) {        if (paddedPacket[i] == 0x00) {          actualEnd = i;        } else {          break;        }      }    } else {      int zeroCount = 0;      for (int i = paddedPacket.length - 1; i >= 0 && zeroCount < 4; i--) {        if (paddedPacket[i] == 0x00) {          zeroCount++;          actualEnd = i;        } else {          break;        }      }    }    return paddedPacket.sublist(0, actualEnd);  }  void recordPattern(TrafficPattern pattern) {    _observedPatterns.add(pattern);    if (_observedPatterns.length > _maxPatternHistory) {      _observedPatterns.removeAt(0);    }  }  TrafficPattern generateMimicPattern() {    if (_observedPatterns.isEmpty) {      return TrafficPattern(        nodeId: 'self',        packetSizes: [_targetPacketSize],        interArrivalTimes: [100],        startTime: DateTime.now(),        endTime: DateTime.now(),        totalPackets: 1,      );    }    final avgSize = _observedPatterns            .map((p) => p.averagePacketSize)            .reduce((a, b) => a + b) /        _observedPatterns.length;    final avgInterval = _observedPatterns            .map((p) => p.averageInterArrivalTime)            .reduce((a, b) => a + b) /        _observedPatterns.length;    return TrafficPattern(      nodeId: 'mimic',      packetSizes: [avgSize.round()],      interArrivalTimes: [avgInterval.round()],      startTime: DateTime.now(),      endTime: DateTime.now().add(Duration(milliseconds: avgInterval.round())),      totalPackets: 10,    );  }  List<Uint8List> generateTrafficBurst(int count) {    final burst = <Uint8List>[];    final pattern = generateMimicPattern();    for (int i = 0; i < count; i++) {      final size = (pattern.averagePacketSize + _random.nextDouble() * 100 - 50)          .round()          .clamp(64, 1500);      burst.add(generateDummyTraffic(size));    }    return burst;  }  Uint8List padToFixedSize(Uint8List packet, int targetSize) {    if (packet.length >= targetSize) {      return packet.sublist(0, targetSize);    }    final padded = Uint8List(targetSize);    padded.setAll(0, packet);    for (int i = packet.length; i < targetSize; i++) {      padded[i] = _random.nextInt(256);    }    return padded;  }  int detectPadding(Uint8List packet) {    if (packet.length <= _targetPacketSize) return 0;    int trailingZeros = 0;    for (int i = packet.length - 1; i >= 0 && packet[i] == 0x00; i--) {      trailingZeros++;    }    if (trailingZeros >= _minPadding) {      return trailingZeros;    }    return 0;  }  bool isSuspiciousPacket(Uint8List packet) {    if (packet.length == 0) return true;    if (packet.length < 64 &&        packet.length != 128 &&        packet.length != 256 &&        packet.length != 512) {      return true;    }    int zeroCount = 0;    for (final byte in packet) {      if (byte == 0x00) zeroCount++;    }    if (zeroCount > packet.length * 0.9) {      return true;    }    return false;  }  Uint8List createChaffPacket() {    final chaffSize = 64 + _random.nextInt(128);    final chaff = Uint8List(chaffSize);    chaff[0] = 0xFF;    chaff[1] = 0x00;    for (int i = 2; i < chaffSize - 4; i++) {      chaff[i] = _random.nextInt(256);    }    final checksum = _calculateChecksum(chaff.sublist(0, chaffSize - 4));    chaff[chaffSize - 4] = (checksum >> 24) & 0xFF;    chaff[chaffSize - 3] = (checksum >> 16) & 0xFF;    chaff[chaffSize - 2] = (checksum >> 8) & 0xFF;    chaff[chaffSize - 1] = checksum & 0xFF;    return chaff;  }  int _calculateChecksum(Uint8List data) {    int sum = 0;    for (int i = 0; i < data.length; i += 2) {      if (i + 1 < data.length) {        sum += (data[i] << 8) + data[i + 1];      } else {        sum += data[i] << 8;      }    }    while (sum >> 16 != 0) {      sum = (sum & 0xFFFF) + (sum >> 16);    }    return ~sum & 0xFFFF;  }  void setTargetPacketSize(int size) {    if (size >= 64 && size <= 1500) {      _targetPacketSize = size;    }  }  Map<String, dynamic> getStatistics() {    return {      'totalPacketsPadded': _totalPacketsPadded,      'totalBytesPadded': _totalBytesPadded,      'averagePaddingPerPacket': _totalPacketsPadded > 0          ? (_totalBytesPadded / _totalPacketsPadded).round()          : 0,      'scheme': _scheme.name,      'targetPacketSize': _targetPacketSize,      'recordedPatterns': _observedPatterns.length,    };  }  void resetStatistics() {    _totalPacketsPadded = 0;    _totalBytesPadded = 0;  }  void dispose() {    _paddedPacketController.close();  }}